ground_truth:
def min_partitions(nums):
    """
    Returns the minimum number of subarrays required to partition 'nums' 
    such that each subarray is sorted in non-decreasing order.
    """
    if not nums:
        return 0

    partitions = 1
    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            partitions += 1

    return partitions
